static robj **luaArgsToRedisArgv(lua_State *lua, int *argc, int *argv_len) {
    int j;
    /* Require at least one argument */
    *argc = lua_gettop(lua);
    if (*argc == 0) {
        luaPushErrorBuff(lua, sdsnew("Please specify at least one argument for this redis lib call"));
        return NULL;
    }

    /* Build the arguments vector (reuse a cached argv from last call) */
    if (lua_argv_size < *argc) {
        lua_argv = zrealloc(lua_argv,sizeof(robj*)* *argc);
        lua_argv_size = *argc;
    }
    *argv_len = lua_argv_size;

    for (j = 0; j < *argc; j++) {
        char *obj_s;
        size_t obj_len;
        char dbuf[64];
        int reused_cached_arg = 0;

        if (lua_type(lua,j+1) == LUA_TNUMBER) {
            /* We can't use lua_tolstring() for number -> string conversion
             * since Lua uses a format specifier that loses precision. */
            lua_Number num = lua_tonumber(lua,j+1);
            obj_len = fpconv_dtoa((double)num, dbuf);
            dbuf[obj_len] = '\0';
            obj_s = dbuf;
        } else {
            obj_s = (char*)lua_tolstring(lua,j+1,&obj_len);
            if (obj_s == NULL) break; /* Not a string. */
        }
        /* Try to use a cached object, updating the SDS header in place. */
        if (j < LUA_CMD_OBJCACHE_SIZE) {
            robj *cached = lua_args_cached_objects[j];
            if (cached != NULL) {
                if (lua_args_cached_objects_len[j] >= obj_len) {
                    sds s = cached->ptr;
                    unsigned char flags = s[-1];
                    switch(flags & SDS_TYPE_MASK) {
                    case SDS_TYPE_5:
                        {
                            unsigned char *fp = ((unsigned char*)s)-1;
                            *fp = SDS_TYPE_5 | (obj_len << SDS_TYPE_BITS);
                            reused_cached_arg = 1;
                        }
                        break;
                    case SDS_TYPE_8:
                        if (obj_len <= SDS_HDR(8,s)->alloc) {
                            SDS_HDR(8,s)->len = obj_len;
                            reused_cached_arg = 1;
                        }
                        break;
                    case SDS_TYPE_16:
                        SDS_HDR(16,s)->len = obj_len;
                        reused_cached_arg = 1;
                        break;
                    case SDS_TYPE_32:
                        SDS_HDR(32,s)->len = obj_len;
                        reused_cached_arg = 1;
                        break;
                    case SDS_TYPE_64:
                        SDS_HDR(64,s)->len = obj_len;
                        reused_cached_arg = 1;
                        break;
                    }
                    if (reused_cached_arg) {
                        memcpy(s,obj_s,obj_len+1);
                        lua_argv[j] = cached;
                        lua_args_cached_objects[j] = NULL;
                    }
                }
            }
        }

        if (!reused_cached_arg) {
            robj *built;
            /* Keep the same EMBSTR/RAW split used by string object creation so
             * small Lua arguments stay packed in a single allocation. */
            if (obj_len <= 44) {
                built = zmalloc(sizeof(robj)+sizeof(struct sdshdr8)+obj_len+1);
                struct sdshdr8 *sh = (void*)(built+1);
                built->type = OBJ_STRING;
                built->encoding = OBJ_ENCODING_EMBSTR;
                built->ptr = sh+1;
                built->refcount = 1;
                built->lru = 0;
                sh->len = obj_len;
                sh->alloc = obj_len;
                sh->flags = SDS_TYPE_8;
                if (obj_len != 0) {
                    memcpy(sh->buf,obj_s,obj_len);
                    sh->buf[obj_len] = '\0';
                } else {
                    sh->buf[0] = '\0';
                }
            } else {
                sds raw = sdsnewlen(obj_s, obj_len);
                built = createObject(OBJ_STRING, raw);
            }
            lua_argv[j] = built;
        }

